/**
 * Shared helpers for the inside-beam figures: build-time data, scales and a depth ramp.
 * The JSON under data/inside-beam is generated by scripts/blog_data.py in
 * github.com/rycerzes/beam-inside from the public rycerzes/beam-expert-atlas export.
 */
import { series } from '$lib/palette';

const raw = import.meta.glob('/src/lib/figures/data/inside-beam/*.json', {
	query: '?raw',
	import: 'default',
	eager: true
}) as Record<string, string>;

export function beamData<T>(name: string): T {
	const source = raw[`/src/lib/figures/data/inside-beam/${name}.json`];
	if (!source) throw new Error(`missing figure data: ${name}`);
	return JSON.parse(source) as T;
}

export type Scale = (v: number) => number;

export function linear(d0: number, d1: number, r0: number, r1: number): Scale {
	return (v) => r0 + ((v - d0) / (d1 - d0)) * (r1 - r0);
}

export function logScale(d0: number, d1: number, r0: number, r1: number): Scale {
	const l0 = Math.log10(d0);
	const l1 = Math.log10(d1);
	return (v) => r0 + ((Math.log10(Math.max(v, d0)) - l0) / (l1 - l0)) * (r1 - r0);
}

function hex(c: string): [number, number, number] {
	return [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16)) as [number, number, number];
}

/** Mix two palette colours; t in [0, 1]. */
export function mix(a: string, b: string, t: number): string {
	const [x, y] = [hex(a), hex(b)];
	const c = x.map((v, i) => Math.round(v + (y[i] - v) * Math.min(1, Math.max(0, t))));
	return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
}

/** Depth ramp shared by every figure: early layers blue, late layers peach. */
export const depthColour = (layer: number) => mix(series.blue, series.peach, (layer - 3) / 48);

export const pct = (v: number, digits = 0) => `${(v * 100).toFixed(digits)}%`;

/** Tokens often start with a space or are pure whitespace; make that visible. */
export const showToken = (t: string) => t.replace(/\n/g, '↵').replace(/\t/g, '⇥').trim() || '␣';

/** Model outputs carry markdown emphasis; the figures show plain text. */
export const plain = (s: string) => s.replace(/\*\*/g, '').replace(/^#+\s/gm, '');
